// Normalise whatever the source gave us into ONE shape.
// Every downstream node depends on these field names and nothing else,
// so adding a second source later means adding a node here, not rewriting
// the pipeline.
return items.map(item => {
  const d = item.json;
  const email = String(d.from || d.textFrom || '').match(/[\w.+-]+@[\w.-]+\.\w+/);
  return {
    json: {
      source: 'imap',
      received_at: d.date || new Date().toISOString(),
      from_email: email ? email[0].toLowerCase() : null,
      subject: String(d.subject || '').trim(),
      body: String(d.textPlain || d.textHtml || '').slice(0, 20000),
      message_id: d.messageId || null
    }
  };
});

// IDEMPOTENCY KEY.
// A retry, a double send, or a re-delivered IMAP message must produce the
// SAME key. We deliberately do not include a timestamp: two identical mails
// arriving a second apart are the same event, not two leads.
const crypto = require('crypto');
return items.map(item => {
  const d = item.json;
  const basis = [d.message_id || '', d.from_email || '', d.subject || ''].join('|');
  d.dedupe_key = crypto.createHash('sha256').update(basis).digest('hex');
  return { json: d };
});

// The prompt asks for a STRICT json shape and forbids prose.
// We still validate the answer afterwards: asking nicely is not a contract.
return items.map(item => {
  const d = item.json;
  d.llm_prompt = [
    'Extract lead data from the email below.',
    'Answer with JSON only, no prose, no code fence.',
    'Schema: {"company":string|null,"contact_name":string|null,',
    '"intent":"quote"|"support"|"partnership"|"other",',
    '"budget_eur":number|null,"score":integer 0-100,"confidence":number 0-1}',
    '',
    'SUBJECT: ' + (d.subject || ''),
    'BODY:',
    (d.body || '').slice(0, 8000)
  ].join('\n');
  return { json: d };
});

// VALIDATE THE MODEL OUTPUT.
// An LLM step is an untrusted input, exactly like a user form. We never let
// its answer reach a write node unchecked: a single stray sentence around
// the JSON would otherwise poison the CRM record.
const INTENTS = ['quote', 'support', 'partnership', 'other'];
return items.map(item => {
  const d = item.json;
  const raw = d.content && d.content[0] ? d.content[0].text : '';
  let parsed = null, reason = null;

  const m = String(raw).match(/\{[\s\S]*\}/);
  if (!m) {
    reason = 'no JSON object in answer';
  } else {
    try { parsed = JSON.parse(m[0]); }
    catch (e) { reason = 'JSON parse failed: ' + e.message; }
  }

  if (parsed) {
    if (typeof parsed.score !== 'number' || parsed.score < 0 || parsed.score > 100) {
      reason = 'score missing or out of range';
    } else if (!INTENTS.includes(parsed.intent)) {
      reason = 'intent not in allowed set';
    } else if (typeof parsed.confidence !== 'number' || parsed.confidence < 0.6) {
      reason = 'confidence below 0.6';
    }
  }

  return { json: Object.assign({}, d, {
    llm_raw: String(raw).slice(0, 2000),
    extraction: parsed,
    valid: !reason,
    invalid_reason: reason
  }) };
});

